package nl.smartstreamlabs.sbwdroneconfig;
import org.junit.jupiter.api.Test;import org.joml.Matrix4d;import org.joml.Vector3d;import static org.junit.jupiter.api.Assertions.*;
class Hgd01FramesTest {
 @Test void r3NativeAnchorsAgreeWithNeutralSbwFrame(){var t=Hgd01Frames.turret(new Matrix4d(),0);var gun=Hgd01Frames.point(Hgd01Frames.gun(t,0),0,0,3.42);assertEquals(0,gun.x,1e-9);assertEquals(2.74,gun.y,1e-9);assertEquals(3.84,gun.z,1e-9);var left=Hgd01Frames.point(Hgd01Frames.laser(t,0,0),0,0,1.4);var right=Hgd01Frames.point(Hgd01Frames.laser(t,0,1),0,0,1.4);assertEquals(.76,left.x,1e-9);assertEquals(-.76,right.x,1e-9);assertEquals(2.94,left.y,1e-9);assertEquals(1.02,left.z,1e-9);var camera=Hgd01Frames.sensor(t,0).transformPosition(new Vector3d());assertEquals(.22,camera.x,1e-9);assertEquals(3.03,camera.y,1e-9);assertEquals(-.1,camera.z,1e-9);}
 @Test void highElevationRotatesAroundEachOwnPivot(){var turret=Hgd01Frames.turret(new Matrix4d(),359);for(int i=0;i<2;i++){var f=Hgd01Frames.laser(turret,-68,i);var d=f.transformDirection(new Vector3d(0,0,1));assertEquals(Math.sin(Math.toRadians(68)),d.y,1e-9);assertEquals(1,d.length(),1e-9);}var muzzle=Hgd01Frames.point(Hgd01Frames.gun(turret,-68),0,0,3.42);assertTrue(muzzle.y>5.8);}
 @Test void fullHullAttitudeAppliedOnce(){var hull=new Matrix4d().translate(100,70,-40).rotateY(.8).rotateX(.12).rotateZ(-.1);var point=Hgd01Frames.point(Hgd01Frames.gun(Hgd01Frames.turret(hull,0),0),0,0,3.42);var recovered=new Matrix4d(hull).invert().transformPosition(point);assertEquals(0,recovered.x,1e-9);assertEquals(2.74,recovered.y,1e-9);assertEquals(3.84,recovered.z,1e-9);}
 @Test void fourSeatOriginsFitDistinctR3Cushions(){for(int i=0;i<4;i++){assertEquals(1.1975,Hgd01Frames.SEAT_ENTITY_Y+.75,1e-9);for(int j=i+1;j<4;j++)assertTrue(Math.hypot(Hgd01Frames.seatX(i)-Hgd01Frames.seatX(j),Hgd01Frames.seatZ(i)-Hgd01Frames.seatZ(j))>1.1);}}
 @Test void rearSectorClearsRaisedFixedEquipment(){assertEquals(5,Hgd01Frames.maximumPitch(359));assertEquals(-12,Hgd01Frames.maximumPitch(180));var muzzle=Hgd01Frames.point(Hgd01Frames.gun(Hgd01Frames.turret(new Matrix4d(),180),Hgd01Frames.maximumPitch(180)),0,0,3.42);assertTrue(muzzle.y>3.4);}
 @Test void trackPathClosesAndReturnsToBindPose(){assertTrue(Hgd01TrackPath.length()>12);var out=new double[3];for(int i=0;i<92;i++){Hgd01TrackPath.pose(i,0,out);assertEquals(0,out[0],1e-8);assertEquals(0,out[1],1e-8);Hgd01TrackPath.pose(i,Hgd01TrackPath.length(),out);assertEquals(0,out[0],1e-8);assertEquals(0,out[1],1e-8);}}
}
